import { IconUnfoldMore } from "@airbus/icons";
import { svgColor, svgUri } from "../../helpers";
import { Input, InputStyling } from "../Input";
import { StyleFn } from "..";

export const Select: StyleFn = (theme, mode) => {
  const { size, color } = theme;
  const { root: input, _small, _info, _valid, _invalid, _adornedStart, _adornedEnd } = Input(theme, mode);
  const { _focused } = InputStyling(theme, mode);
  const bgSvgColor = color.text.accent.corporate[mode]

  return {
    root: {
      ...input,
      alignItems: "center",
      paddingRight: size.spacing[32],
      backgroundRepeat: "no-repeat",
      backgroundPosition: "right 1rem top 50%",
      backgroundImage: svgUri(svgColor(IconUnfoldMore.data, bgSvgColor)),
      backgroundSize: size.spacing[20],
      "&:hover": {
        cursor: "pointer",
      },
      "&:disabled": {
        ...input["&:disabled"],
        pointerEvents: "auto",
      },
      "&:disabled:hover": {
        cursor: "not-allowed",
      },
      // FIXME select html elements have a ":read-only" pseudo selector by default
      "&$root&:read-only": {},
      "&:focus, &:focus-within": _focused,
    },
    _small,
    _info,
    _valid,
    _invalid,
    _hasPlaceholder: {
      color: color.text.neutral.strong[mode],
    },
    _adornedStart: _adornedStart,
    _adornedEnd: _adornedEnd,
  };
};
